def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    frames = []
    frame_colors = set()
    for color in {v for row in grid for v in row if v}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if len(cells) == 2 * (r1-r0+c1-c0):
            frames.append((color, r0, r1, c0, c1))
            frame_colors.add(color)
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if grid[r][c] == color:
                    out[r][c] = color
    marker_counts = {}
    for row in grid:
        for v in row:
            if v and v not in frame_colors:
                marker_counts[v] = marker_counts.get(v, 0) + 1
    available = set(marker_counts)
    for color, r0, r1, c0, c1 in sorted(frames, key=lambda x: (x[2]-x[1]-1)*(x[4]-x[3]-1)):
        spots = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2 == 0]
        if not available:
            continue
        marker = min(available, key=lambda v: abs(marker_counts[v]-len(spots)))
        available.remove(marker)
        for r,c in spots:
            out[r][c] = marker
    return out
